('9g3-w9-p233-example6-1',$question_json${"id":"9g3-w9-p233-example6-1","type":"MCQ","exam":"9th week practice","examWeek":9,"classroom":"9G3","topic":"Linear functions","prompt":"Which graph represents $y=2$? Each square represents 1 unit.","promptAr":"أي رسم يمثل $y=2$؟ كل مربع يمثل وحدة واحدة.","answer":"The graph of $y=2$ is a horizontal line through $(0,2)$, with slope 0.","answerAr":"الإجابة الصحيحة: $y=2$. الرسم خط أفقي يمر بالنقطة $(0,2)$ وميله صفر.","difficulty":"Standard","marks":1,"diagram":"none","image":"","options":["$y=1x+2$","$y=2$","$y=-2$","Vertical line"],"optionsAr":["$y=1x+2$","$y=2$","$y=-2$","Vertical line"],"correctIndex":1,"sourceQuestion":6,"sourcePart":"Example","linearChoices":{"bounds":[-5,5,-5,5],"target":{"kind":"line","m":0,"b":2},"choices":[{"kind":"line","m":1,"b":2},{"kind":"line","m":0,"b":2},{"kind":"line","m":0,"b":-2},{"kind":"vertical","x":2}]},"sourcePage":233}$question_json$::jsonb),
('9g3-w9-p233-example6-2',$question_json${"id":"9g3-w9-p233-example6-2","type":"MCQ","exam":"9th week practice","examWeek":9,"classroom":"9G3","topic":"Linear functions","prompt":"Which graph represents $y=1$? Each square represents 1 unit.","promptAr":"أي رسم يمثل $y=1$؟ كل مربع يمثل وحدة واحدة.","answer":"The graph of $y=1$ is a horizontal line through $(0,1)$, with slope 0.","answerAr":"الإجابة الصحيحة: $y=1$. الرسم خط أفقي يمر بالنقطة $(0,1)$ وميله صفر.","difficulty":"Standard","marks":1,"diagram":"none","image":"","options":["Vertical line","$y=1x+1$","$y=1$","$y=-1$"],"optionsAr":["Vertical line","$y=1x+1$","$y=1$","$y=-1$"],"correctIndex":2,"sourceQuestion":6,"sourcePart":"Check","linearChoices":{"bounds":[-5,5,-5,5],"target":{"kind":"line","m":0,"b":1},"choices":[{"kind":"vertical","x":1},{"kind":"line","m":1,"b":1},{"kind":"line","m":0,"b":1},{"kind":"line","m":0,"b":-1}]},"sourcePage":233}$question_json$::jsonb)
